import re
from pathlib import Path

errors = []
links = 0
for page in Path('docs').rglob('*.md'):
    for target in re.findall(r'(?<!!)\[[^\]]*\]\(([^)]+)\)', page.read_text()):
        if '://' in target:
            continue
        filename, _, anchor = target.partition('#')
        destination = page.parent / filename if filename else page
        links += 1
        if not destination.is_file():
            errors.append(f'{page}: missing {target}')
        elif anchor:
            headings = re.findall(r'^#+\s+(.+)$', destination.read_text(), re.M)
            anchors = {re.sub(r'[^\w\- ]', '', h.lower()).replace(' ', '-') for h in headings}
            if anchor not in anchors:
                errors.append(f'{page}: missing anchor {target}')
if errors:
    raise SystemExit('\n'.join(errors))
print(f'Checked {links} local documentation links; all files and anchors resolve.')
